    $maleBlock = '';
    $femaleBlock = '';

    if (preg_match('/MALE\s*\{(.*)\}\s*FEMALE\s*\{(.*)\}\s*$/s', $normalized, $m)) {
        $maleBlock = $m[1];
        $femaleBlock = $m[2];
    } else {
        $parts = preg_split('/\bFEMALE\b/', $normalized, 2);
        if (count($parts) === 2) {
            $maleBlock = preg_replace('/.*\bMALE\b/s', '', $parts[0], 1);
            $femaleBlock = $parts[1];
        } else {
            $maleBlock = preg_replace('/.*\bMALE\b/s', '', $normalized, 1);
        }
    }

    $maleBlock = trim($maleBlock);
    $femaleBlock = trim($femaleBlock);

    if ($maleBlock !== '' && $maleBlock[0] === '{') {
        $maleBlock = ltrim(substr($maleBlock, 1));
    }
    if ($femaleBlock !== '' && $femaleBlock[0] === '{') {
        $femaleBlock = ltrim(substr($femaleBlock, 1));
    }

    $maleBlock = trim($maleBlock);
    $femaleBlock = trim($femaleBlock);

    if ($maleBlock !== '' && substr($maleBlock, -1) === '}') {
        $maleBlock = rtrim(substr($maleBlock, 0, -1));
    }
    if ($femaleBlock !== '' && substr($femaleBlock, -1) === '}') {
        $femaleBlock = rtrim(substr($femaleBlock, 0, -1));
    }

    $maleItems = preg_split('/\n\s*\n+/', trim($maleBlock));
    $femaleItems = preg_split('/\n\s*\n+/', trim($femaleBlock));

    if (is_array($maleItems)) {
        foreach ($maleItems as $item) {
            $item = trim($item);
            if ($item !== '') {
                $out['male'][] = $item;
            }
        }
    }

    if (is_array($femaleItems)) {
        foreach ($femaleItems as $item) {
            $item = trim($item);
            if ($item !== '') {
                $out['female'][] = $item;
            }
        }
    }

    return $out;
}

return parse_remarks_text($raw);

